{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT cl.service_name caller, sv.service_name callee, COUNT(*) n, quantile_cont(cl.duration/1e6,0.5) client_p50_ms, quantile_cont(sv.duration/1e6,0.5) server_p50_ms FROM abnormal_traces cl JOIN abnormal_traces sv ON sv.parent_span_id=cl.span_id AND sv.trace_id=cl.trace_id WHERE cl.attr_span_kind='Client' AND sv.attr_span_kind='Server' AND cl.service_name='ts-seat-service' AND cl.span_name='POST' GROUP BY 1,2", "claim": "Seat's outgoing POST client spans to order-service take about 1438 ms, while the order server spans take about 3 ms."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, COUNT(*) n, quantile_cont(duration/1e6,0.5) p50_ms, quantile_cont(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name IN ('SeatController.getLeftTicketOfInterval','GET','POST') GROUP BY 1,2", "claim": "Seat's left_tickets handling is about 1447 ms p50 while its GET calls to config stay about 6 ms."},
        {"kind": "metric", "sql": "SELECT metric, attr_source, attr_destination, ROUND(AVG(value),3) v FROM abnormal_metrics_sum WHERE metric='hubble_flows_processed_total' AND attr_source='ts2/ts-seat-service-5c44567799-f6nln' AND attr_destination IN ('ts2/ts-order-service-687867685d-dkkt8','ts2/ts-config-service-78cd5b655b-hqjzz') GROUP BY 1,2,3", "claim": "Hubble shows no drops on seat's connections, so the extra delay is not a network loss or partition."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-seat-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT cl.service_name caller, sv.service_name callee, COUNT(*) n, quantile_cont(cl.duration/1e6,0.5) client_p50_ms, quantile_cont(sv.duration/1e6,0.5) server_p50_ms FROM abnormal_traces cl JOIN abnormal_traces sv ON sv.parent_span_id=cl.span_id AND sv.trace_id=cl.trace_id WHERE cl.attr_span_kind='Client' AND sv.attr_span_kind='Server' AND cl.service_name='ts-travel-service' AND sv.service_name='ts-seat-service' GROUP BY 1,2", "claim": "Travel's calls to seat take about 1450 ms at both client and server, inheriting seat's delay."}]},
    {"from": "ts-seat-service", "to": "ts-preserve-service", "evidence": [{"kind": "trace", "sql": "SELECT cl.service_name caller, sv.service_name callee, COUNT(*) n, quantile_cont(cl.duration/1e6,0.5) client_p50_ms, quantile_cont(sv.duration/1e6,0.5) server_p50_ms FROM abnormal_traces cl JOIN abnormal_traces sv ON sv.parent_span_id=cl.span_id AND sv.trace_id=cl.trace_id WHERE cl.attr_span_kind='Client' AND sv.attr_span_kind='Server' AND cl.service_name='ts-preserve-service' AND sv.service_name='ts-seat-service' GROUP BY 1,2", "claim": "Preserve's calls to seat take about 1447 ms, matching seat's server-side delay."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT cl.service_name caller, sv.service_name callee, COUNT(*) n, quantile_cont(cl.duration/1e6,0.5) client_p50_ms, quantile_cont(sv.duration/1e6,0.5) server_p50_ms FROM abnormal_traces cl JOIN abnormal_traces sv ON sv.parent_span_id=cl.span_id AND sv.trace_id=cl.trace_id WHERE cl.attr_span_kind='Client' AND sv.attr_span_kind='Server' AND cl.service_name='ts-route-plan-service' AND sv.service_name='ts-travel-service' GROUP BY 1,2", "claim": "Route-plan's calls to travel take about 8773 ms, with travel's server spans showing the same time."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT cl.service_name caller, sv.service_name callee, COUNT(*) n, quantile_cont(cl.duration/1e6,0.5) client_p50_ms, quantile_cont(sv.duration/1e6,0.5) server_p50_ms FROM abnormal_traces cl JOIN abnormal_traces sv ON sv.parent_span_id=cl.span_id AND sv.trace_id=cl.trace_id WHERE cl.attr_span_kind='Client' AND sv.attr_span_kind='Server' AND cl.service_name='ts-travel-plan-service' AND sv.service_name='ts-route-plan-service' GROUP BY 1,2", "claim": "Travel-plan's calls to route-plan take about 400 ms at client and server, inheriting the upstream delay."}]},
    {"from": "ts-travel-service", "to": "ts-preserve-service", "evidence": [{"kind": "trace", "sql": "SELECT cl.service_name caller, sv.service_name callee, COUNT(*) n, quantile_cont(cl.duration/1e6,0.5) client_p50_ms, quantile_cont(sv.duration/1e6,0.5) server_p50_ms FROM abnormal_traces cl JOIN abnormal_traces sv ON sv.parent_span_id=cl.span_id AND sv.trace_id=cl.trace_id WHERE cl.attr_span_kind='Client' AND sv.attr_span_kind='Server' AND cl.service_name='ts-preserve-service' AND sv.service_name='ts-travel-service' GROUP BY 1,2", "claim": "Preserve's calls to travel take about 2962 ms, inheriting travel's delay."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, COUNT(*) n, quantile_cont(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-ui-dashboard') AND span_name='POST' GROUP BY 1,2", "claim": "Travel-plan POST p95 reaches about 17.7 s, and the dashboard's p95 also rises from 200 to 477 ms."}]},
    {"from": "ts-travel-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT cl.service_name caller, sv.service_name callee, COUNT(*) n, quantile_cont(cl.duration/1e6,0.5) client_p50_ms, quantile_cont(sv.duration/1e6,0.5) server_p50_ms FROM abnormal_traces cl JOIN abnormal_traces sv ON sv.parent_span_id=cl.span_id AND sv.trace_id=cl.trace_id WHERE cl.attr_span_kind='Client' AND sv.attr_span_kind='Server' AND sv.service_name='ts-travel-service' AND cl.service_name='ts-ui-dashboard' GROUP BY 1,2", "claim": "Dashboard's calls to travel take about 399 ms at client and about 8.8 s at travel's server in the abnormal period."}]},
    {"from": "ts-preserve-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT cl.service_name caller, sv.service_name callee, COUNT(*) n, quantile_cont(cl.duration/1e6,0.5) client_p50_ms, quantile_cont(sv.duration/1e6,0.5) server_p50_ms FROM abnormal_traces cl JOIN abnormal_traces sv ON sv.parent_span_id=cl.span_id AND sv.trace_id=cl.trace_id WHERE cl.attr_span_kind='Client' AND sv.attr_span_kind='Server' AND sv.service_name='ts-preserve-service' AND cl.service_name='ts-ui-dashboard' GROUP BY 1,2", "claim": "Dashboard's calls to preserve rise to about 4.7 s p95, inheriting preserve's downstream delay."}]}
  ]
}
